events.command:
API_KEY=$(cat $GALAXY_API_KEY_FILE)
# Submit Filter Tabular with regex for < 10 methylation
JOB1=$(curl -s -X POST "https://usegalaxy.org/api/tools" \
  -H "x-api-key: $API_KEY" \
  -H "Content-Type: application/json" \
  -d '{
    "history_id": "bbd44e69cb8906b541681354f419c700",
    "tool_id": "toolshed.g2.bx.psu.edu/repos/iuc/filter_tabular/filter_tabular/3.3.1",
    "input_format": "21.01",
    "inputs": {
      "input": {"src": "hda", "id": "f9cad7b01a47213591e0f0886cc43b24"},
      "linefilters": [
        {
          "filter": {
            "__current_case__": "regex",
            "regex_pattern": "^([^,]*,){6}[0-9](\\\\.[0-9]*)?,",
            "regex_action": "include_match"
          }
        }
      ]
    }
  }' | python3 -c "import json,sys; d=json.load(sys.stdin); print('Job ID:', d.get('id','N/A')); print('Outputs:', [(o['name'], o['state'], o['id']) for o in d.get('outputs',[])])" 2>&1)

echo "---"
echo "$JOB1"

