python3 << 'PYEOF'
import json, subprocess, os

API_KEY = open(os.environ["GALAXY_API_KEY_FILE"]).read().strip()

# The regex for column 7 < 10 with TAB-separated data
regex_lt10 = r"^([^\t]*\t){6}[0-9](\.[0-9]*)?\t"
# The regex for column 7 > 90 with TAB-separated data
regex_gt90 = r"^([^\t]*\t){6}(9[1-9](\.[0-9]*)?|90\.[0-9]*[1-9][0-9]*|100(\.0*)?)\t"

for label, regex in [("lt10", regex_lt10), ("gt90", regex_gt90)]:
    payload = {
        "history_id": "bbd44e69cb8906b541681354f419c700",
        "tool_id": "toolshed.g2.bx.psu.edu/repos/iuc/filter_tabular/filter_tabular/3.3.1",
        "input_format": "21.01",
        "inputs": {
            "input": {"src": "hda", "id": "f9cad7b01a47213591e0f0886cc43b24"},
            "linefilters": [
                {
                    "filter": {
                        "__current_case__": "regex",
                        "regex_pattern": regex,
                        "regex_action": "include_match"
                    }
                }
            ]
        }
    }

    result = subprocess.run(
        ["curl", "-s", "-X", "POST", "https://usegalaxy.org/api/tools",
         "-H", f"x-api-key: {API_KEY}",
         "-H", "Content-Type: application/json",
         "-d", json.dumps(payload)],
        capture_output=True, text=True
    )

    resp = json.loads(result.stdout)
    outputs = resp.get("outputs", [])
    for o in outputs:
        print(f"Filter {label}: name={o['name']}, state={o['state']}, id={o['id']}")

PYEOF

